'use strict';
const STORAGE='aptech-ai-session4-v1';
const INITIAL_CODE='enrolled = True\ncompleted_safety = False\nsuspended = False\nmay_enter = enrolled and completed_safety and not suspended\nprint(may_enter)\nif may_enter:\n    print("Lab access granted")\nelse:\n    print("Check requirements")';
const fresh={slide:0,answers:{},worksheet:{},knowledgeType:'declarative',representation:'frame',relation:'Amina',facts:{enrolled:true,completed_safety:true,suspended:false},ruleStep:0,p:true,q:false,operator:'and',people:{Amina:true,Bola:false,Chidi:true},threshold:50,baseline:false,code:INITIAL_CODE,codeOutput:'',genQuestion:'hours',grounded:true,genOutput:''};
let state;try{state={...structuredClone(fresh),...JSON.parse(localStorage.getItem(STORAGE)||'null')};}catch(e){state=structuredClone(fresh);}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){try{localStorage.setItem(STORAGE,JSON.stringify(state));return true;}catch(e){return false;}}
const sections=[{name:'Reconnect and set the task',time:10,start:0},{name:'Represent knowledge',time:20,start:3},{name:'Knowledge, planning, and decisions',time:10,start:10},{name:'Reasoning and logic',time:20,start:14},{name:'Rules in beginner Python',time:15,start:22},{name:'Measure performance',time:25,start:26},{name:'Emerging and generative AI',time:10,start:33},{name:'Practise and explain',time:10,start:36}];
function sectionFor(i){return sections.filter(s=>s.start<=i).at(-1);}
function panel(title,text,classes=''){return '<article class="panel stack '+classes+'"><h3>'+title+'</h3><p>'+text+'</p></article>';}
function note(text){return '<div class="note">'+text+'</div>';}
function field(key,label,placeholder=''){return '<label>'+esc(label)+'<textarea class="answer" data-field="'+key+'" placeholder="'+esc(placeholder)+'">'+esc(state.worksheet[key]||'')+'</textarea></label>';}
const quizData={recall:{q:'A map shows a route to the lab. What else might an assistant need before recommending entry?',options:['Only the route. Reaching the door proves permission.','Relevant facts and access rules, such as completed safety training.'],correct:1,why:'Search can find a route to a goal. Knowledge and rules can determine whether an action is appropriate or permitted in the defined task.'},unknown:{q:'The training field is missing. Can we conclude that Amina never completed training?',options:['Yes. A missing record always proves False.','No. Missing information can mean that the answer is unknown.'],correct:1,why:'Absence of a record does not automatically prove its opposite. This lesson keeps True, False, and Unknown distinct in the knowledge lab.'},deduction:{q:'Every trained student may book a practice slot. Amina is trained. What follows under these premises?',options:['Amina may book a practice slot.','Every student is trained.','Amina has already booked a slot.'],correct:0,why:'Deduction applies the general rule to the specific fact. It does not establish training for everyone or claim that an action already happened.'},reverse:{q:'If it rains, the courtyard is wet. The courtyard is wet. Does that prove it rained?',options:['Yes. The implication works in both directions.','No. A sprinkler or cleaning could also make it wet.'],correct:1,why:'A consequence does not prove a particular cause. Inferring rain is a possible explanation, not a guaranteed deduction.'},accuracy:{q:'An always-normal filter gets 95 of 100 messages correct. All 5 spam messages slip through. Is accuracy enough to evaluate it?',options:['Yes. 95% settles the question.','No. We also need to measure how many spam messages it catches.'],correct:1,why:'Class imbalance can hide failure on the important class. This filter has spam recall 0/5 = 0% despite 95% accuracy.'},exit1:{q:'Which representation makes a student’s named attributes easy to inspect?',options:['A frame with slots such as name and training status.','An unexplained number with no attribute meaning.'],correct:0,why:'A frame groups named attributes about an entity. The format helps a system and a person find the relevant facts.'},exit2:{q:'Precision answers which question in our spam filter?',options:['Of all real spam, how much did we flag?','Of everything we flagged as spam, how much was really spam?'],correct:1,why:'Precision is TP/(TP+FP). Recall answers the first question using TP/(TP+FN).'},exit3:{q:'A generated answer sounds confident but has no supporting evidence. What should the assistant do?',options:['Treat confidence as proof.','Check evidence and say when the available information is insufficient.'],correct:1,why:'Generated language can contain unsupported claims. Relevant evidence and verification help, but retrieval alone does not guarantee correctness.'}};
function quiz(id){const q=quizData[id],a=state.answers[id];return '<div class="stack"><h3>'+q.q+'</h3><div class="choices">'+q.options.map((o,i)=>'<button data-quiz="'+id+'" data-choice="'+i+'" aria-pressed="'+(a===i)+'">'+o+'</button>').join('')+'</div><div class="feedback '+(a!==undefined&&a!==q.correct?'bad':'')+'" id="feedback-'+id+'" aria-live="polite">'+(a===undefined?'':(a===q.correct?'Yes. ':'Review the reason. ')+q.why)+'</div></div>';}
const knowledgeTypes={declarative:['Declarative knowledge','Facts or claims about the world.','“Amina is enrolled.” We can record the claim and its source.'],procedural:['Procedural knowledge','How to carry out a task.','A lab booking procedure: check eligibility, select a slot, confirm the booking.'],heuristic:['Heuristic knowledge','A useful rule of thumb that can have exceptions.','“Try the less busy lab first.” It may help but cannot guarantee a free seat.'],structural:['Structural knowledge','Relationships between entities or concepts.','“Lab 2 is part of the science building.” The relationship supports location queries.'],meta:['Meta-knowledge','Knowledge about knowledge, its source, or how to use it.','“This safety record came from the training officer yesterday.” Provenance helps judge whether to trust or update it.']};
function typeHTML(){const t=knowledgeTypes[state.knowledgeType];return '<h3>'+t[0]+'</h3><p>'+t[1]+'</p>'+note(t[2]);}
const representations={frame:['Frame','<table class="small-table"><tbody><tr><th>Slot</th><th>Value</th></tr><tr><td>name</td><td>Amina</td></tr><tr><td>enrolled</td><td>True</td></tr><tr><td>completed_safety</td><td>True</td></tr><tr><td>record_source</td><td>Fictional training register</td></tr></tbody></table>','A frame groups named attributes around one entity. A Python dictionary can encode this small frame.'],graph:['Semantic network','<div class="semantic-list"><div class="relation04"><b>Amina</b><span>is an instance of</span><b>Student</b></div><div class="relation04"><b>Amina</b><span>completed</span><b>Safety training</b></div></div>','Nodes name entities or concepts. Labelled edges tell us what their relationship means.'],logic:['Logic','<pre class="code">Enrolled(Amina)\nCompletedSafety(Amina)</pre>','Predicates name properties of an entity. These are two specific facts, not a claim about every student.'],rules:['Rule','<pre class="code">IF enrolled AND completed_safety\nTHEN eligible_to_book</pre>','A rule links conditions to a conclusion. It is a general policy to apply to a student, rather than a fact about Amina alone.']};
function representationHTML(){const r=representations[state.representation];return '<h3>'+r[0]+'</h3>'+r[1]+'<p>'+r[2]+'</p>';}
function and3(...values){return values.includes(false)?false:values.includes(null)?null:true;}
function not3(v){return v===null?null:!v;}
function knowledgeTrace(facts){const trained=facts.completed_safety,eligible=and3(facts.enrolled,trained),may_enter=and3(eligible,not3(facts.suspended));return [{name:'trained',value:trained,rule:'trained = completed_safety',why:'For this toy policy, trained has exactly the safety-completion record’s value.'},{name:'eligible',value:eligible,rule:'eligible = enrolled AND trained',why:'Both enrolment and training are required.'},{name:'may_enter',value:may_enter,rule:'may_enter = eligible AND NOT suspended',why:'The suspension record must explicitly say False for this toy policy.'}];}
const truth=v=>v===null?'Unknown':v?'True':'False';
function triSelect(key,label){return '<label class="choice04">'+label+'<select data-fact="'+key+'">'+[['true','True'],['false','False'],['unknown','Unknown']].map(([v,t])=>'<option value="'+v+'" '+((state.facts[key]===null?'unknown':String(state.facts[key]))===v?'selected':'')+'>'+t+'</option>').join('')+'</select></label>';}
function rulesHTML(){return '<div class="stack"><div class="fact-grid">'+triSelect('enrolled','Enrolled')+triSelect('completed_safety','Safety completed')+triSelect('suspended','Suspended')+'</div><div class="row"><button id="ruleStep" class="accent">Apply next rule</button><button id="ruleRun">Apply all rules</button><button id="ruleReset">Reset trace</button></div><div id="ruleTrace" class="trace04" aria-live="polite"></div><div id="ruleVerdict" class="verdict04 pending" aria-live="polite"></div><p class="caption">Fictional policy. This lab uses explicit three-valued conditions. Unknown is not Python False.</p></div>';}
function updateRules(){const trace=knowledgeTrace(state.facts),step=state.ruleStep;document.getElementById('ruleTrace').innerHTML=trace.map((t,i)=>'<div class="trace-rule '+(step>i?'derived ':'')+(step===i?'active-rule':'')+'"><b>'+esc(t.rule)+'</b><span>'+t.name+': '+(step>i?truth(t.value):'not evaluated')+'</span><span class="why">'+t.why+'</span></div>').join('');const f=document.getElementById('ruleVerdict'),v=trace[2].value;f.classList.toggle('pending',step<3||v!==true);f.innerHTML=step<3?'<b>Trace in progress</b><span>Predict the next conclusion, then apply its rule.</span>':v===true?'<b>Access condition satisfied</b><span>All required conditions are explicitly supported in this fictional record.</span>':v===false?'<b>Access condition not satisfied</b><span>At least one required condition is explicitly false. Inspect which fact blocks the rule.</span>':'<b>Insufficient evidence</b><span>A required fact is unknown. Ask for the missing record before recommending entry.</span>';document.getElementById('ruleStep').disabled=step>=3;}
function connective(p,q,op){return op==='and'?p&&q:op==='or'?p||q:op==='not'?!p:!p||q;}
function logicHTML(){return '<div class="lab04"><div class="stack"><p>P = Amina is enrolled<br>Q = Amina completed safety training</p><div class="logic-switches"><button id="toggleP" aria-pressed="'+state.p+'">P: '+truth(state.p)+'</button><button id="toggleQ" aria-pressed="'+state.q+'">Q: '+truth(state.q)+'</button></div><label class="choice04">Operation<select id="logicOperator">'+[['and','AND (P ∧ Q)'],['or','OR (P ∨ Q)'],['not','NOT P (¬P)'],['implies','IMPLIES (P ⇒ Q)']].map(([v,n])=>'<option value="'+v+'" '+(v===state.operator?'selected':'')+'>'+n+'</option>').join('')+'</select></label><div id="logicResult" class="logic-result" aria-live="polite"></div><p id="logicReason" class="caption"></p></div><div class="panel stack"><h3>Truth table</h3><table class="small-table logic-table"><thead><tr><th>P</th><th>Q</th><th id="logicHeading">Result</th></tr></thead><tbody id="logicRows"></tbody></table><p class="caption">Classical propositional logic uses True and False. Missing facts require an additional modelling choice.</p></div></div>';}
function updateLogic(){const names={and:'P AND Q',or:'P OR Q',not:'NOT P',implies:'P IMPLIES Q'},reasons={and:'AND is true only when both conditions are true.',or:'OR is inclusive: at least one condition must be true. Both may be true.',not:'NOT reverses P. Q does not affect this operation.',implies:'An implication is false only when P is true and Q is false. A true implication alone does not establish either fact.'};document.getElementById('logicResult').textContent=names[state.operator]+' = '+truth(connective(state.p,state.q,state.operator));document.getElementById('logicReason').textContent=reasons[state.operator];document.getElementById('logicHeading').textContent=names[state.operator];document.getElementById('logicRows').innerHTML=[true,false].flatMap(p=>[true,false].map(q=>'<tr class="'+(state.p===p&&state.q===q?'active-row':'')+'"><td>'+truth(p)+'</td><td>'+truth(q)+'</td><td>'+truth(connective(p,q,state.operator))+'</td></tr>')).join('');}
function predicateHTML(){return '<div class="stack"><p>CompletedSafety(x) means “person x completed safety training”. Click a person to change the fact.</p><div class="person-grid">'+Object.entries(state.people).map(([p,v])=>'<button data-person="'+p+'" aria-pressed="'+v+'"><b>'+p+'</b><span>Completed safety: '+truth(v)+'</span></button>').join('')+'</div><div id="predicateResult" class="grid two" aria-live="polite"></div><p class="caption">For this exercise the domain contains exactly Amina, Bola, and Chidi. Real-world “everyone” needs a clearly specified domain.</p></div>';}
function updatePredicates(){const values=Object.values(state.people);document.getElementById('predicateResult').innerHTML=panel('For every person: ∀x CompletedSafety(x)','Result: <b>'+truth(values.every(Boolean))+'</b>. Every member of our three-person domain must satisfy the property.')+panel('There exists a person: ∃x CompletedSafety(x)','Result: <b>'+truth(values.some(Boolean))+'</b>. One supporting example is enough.');}
const messages=[{id:'M01',spam:true,score:92},{id:'M02',spam:true,score:81},{id:'M03',spam:true,score:64},{id:'M04',spam:true,score:39},{id:'M05',spam:false,score:75},{id:'M06',spam:false,score:55},{id:'M07',spam:false,score:48},{id:'M08',spam:false,score:31},{id:'M09',spam:false,score:21},{id:'M10',spam:false,score:15},{id:'M11',spam:false,score:8},{id:'M12',spam:false,score:2}];
function metricsAt(threshold,baseline=false){const c={tp:0,fp:0,fn:0,tn:0};for(const m of messages){const pred=!baseline&&m.score>=threshold;c[m.spam?(pred?'tp':'fn'):(pred?'fp':'tn')]++;}const total=c.tp+c.fp+c.fn+c.tn;return {...c,accuracy:(c.tp+c.tn)/total,precision:c.tp+c.fp?c.tp/(c.tp+c.fp):null,recall:c.tp+c.fn?c.tp/(c.tp+c.fn):null,f1:2*c.tp+c.fp+c.fn?2*c.tp/(2*c.tp+c.fp+c.fn):null};}
const pct=v=>v===null?'Undefined':(v*100).toFixed(1)+'%';
function metricsHTML(){return '<div class="metric04-layout"><div class="stack"><label class="threshold04" for="threshold">Flag spam when score ≥ threshold: <output id="thresholdValue">'+(state.threshold/100).toFixed(2)+'</output><input id="threshold" type="range" min="0" max="100" step="1" value="'+state.threshold+'" '+(state.baseline?'disabled':'')+'></label><div class="threshold-presets"><button data-threshold="35">0.35</button><button data-threshold="50">0.50</button><button data-threshold="80">0.80</button><button id="baselineBtn" aria-pressed="'+state.baseline+'">Always normal</button></div><div id="messageGrid" class="message-grid04"></div><div id="messageDetail" class="metric-detail04" aria-live="polite">Select a message to explain its result.</div><p class="caption">12 fictional labelled messages: 4 spam, 8 normal. Scores are invented model outputs and need not be calibrated probabilities.</p></div><div class="stack"><div id="confusionMatrix" class="matrix04" aria-label="Confusion counts" aria-live="polite"></div><div id="metricSummary" class="metric-summary04" aria-live="polite"></div><p id="metricExplanation" class="caption"></p></div></div>';}
function messageCategory(m){const predicted=!state.baseline&&m.score>=state.threshold;return m.spam?(predicted?'tp':'fn'):(predicted?'fp':'tn');}
function updateMetrics(){const m=metricsAt(state.threshold,state.baseline),labels={tp:'True positive: spam caught',fp:'False positive: normal flagged',fn:'False negative: spam missed',tn:'True negative: normal kept'};document.getElementById('thresholdValue').textContent=state.baseline?'always normal':(state.threshold/100).toFixed(2);document.getElementById('threshold').disabled=state.baseline;document.getElementById('baselineBtn').setAttribute('aria-pressed',state.baseline);document.querySelectorAll('[data-threshold]').forEach(b=>b.setAttribute('aria-pressed',!state.baseline&&Number(b.dataset.threshold)===state.threshold));document.getElementById('messageGrid').innerHTML=messages.map(m=>{const c=messageCategory(m);return '<button class="message04 '+(['fp','fn'].includes(c)?'error-message':'')+'" data-message="'+m.id+'" aria-label="'+m.id+', actual '+(m.spam?'spam':'normal')+', score '+m.score/100+', '+labels[c]+'"><b>'+m.id+' · '+(m.score/100).toFixed(2)+'</b><span>Actual: '+(m.spam?'spam':'normal')+'</span><span>Result: '+c.toUpperCase()+'</span></button>';}).join('');document.getElementById('confusionMatrix').innerHTML=['tp','fp','fn','tn'].map(k=>'<div class="matrix-cell04 '+(['fp','fn'].includes(k)?'error-cell':'')+'">'+labels[k]+'<b>'+m[k]+'</b></div>').join('');document.getElementById('metricSummary').innerHTML=[['Accuracy',m.accuracy,(m.tp+m.tn)+' / 12'],['Precision',m.precision,m.tp+' / '+(m.tp+m.fp)],['Recall',m.recall,m.tp+' / '+(m.tp+m.fn)],['F1',m.f1,2*m.tp+' / '+(2*m.tp+m.fp+m.fn)]].map(([n,v,f])=>'<div class="metric-stat04">'+n+'<b>'+pct(v)+'</b><small>'+f+(v===null?' · zero denominator':'')+'</small></div>').join('');document.getElementById('metricExplanation').textContent=state.baseline?'Always normal catches 0 of 4 spam. Precision is undefined because nothing is flagged. Recall and F1 are 0%.':'Lower thresholds flag more messages in this fixed dataset. Compare the extra spam caught with the extra normal messages flagged.';}
const referenceFacts={hours:{fact:'Lab 2 opens at 09:00 and closes at 17:00 on weekdays.',source:'F1 · fictional campus handbook'},training:{fact:'Students need completed safety training before lab entry.',source:'F2 · fictional campus handbook'}};
function groundedAnswer(question,grounded){if(!grounded)return {text:question==='hours'?'Lab 2 opens at 08:00 every day.':question==='training'?'All enrolled students can enter without safety training.':'The lab booking fee is ₦2,000.',supported:false,why:'Scripted unsupported answer. The supplied facts do not justify this claim.'};const f=referenceFacts[question];return f?{text:f.fact+' ['+(question==='hours'?'F1':'F2')+']',supported:true,why:'This scripted answer quotes the matching supplied fact. A real model still needs claim-by-claim checking.'}:{text:'The supplied handbook excerpt does not state a booking fee. Ask the campus office or consult the full handbook.',supported:true,why:'The assistant reports the evidence limit instead of inventing a fee.'};}
function generativeHTML(){return '<div class="lab04"><div class="stack"><h3>Supplied evidence</h3><div class="retrieval04">'+Object.values(referenceFacts).map(f=>'<div class="fact-card04">'+f.fact+'<small>'+f.source+'</small></div>').join('')+'</div><label class="choice04">Question<select id="genQuestion">'+[['hours','When does Lab 2 open?'],['training','Is safety training required?'],['fee','What is the lab booking fee?']].map(([v,n])=>'<option value="'+v+'" '+(state.genQuestion===v?'selected':'')+'>'+n+'</option>').join('')+'</select></label><label class="row"><input id="grounded" type="checkbox" '+(state.grounded?'checked':'')+'> Use only the supplied facts</label><button id="generateDemo" class="accent">Show scripted answer</button></div><div class="stack"><h3>Answer to inspect</h3><div id="genAnswer" class="gen-answer04" aria-live="polite">'+esc(state.genOutput||'Predict what the evidence supports, then show the answer.')+'</div><p id="genWhy" class="caption"></p><p class="caption">Offline, scripted comparison. This page does not call an AI model. The fee in the unsupported example is invented.</p></div></div>';}
const slides=[
{title:'What does the AI know?',kicker:'Session 04 · knowledge, logic, and performance',html:()=>'<div class="grid hero04"><div class="stack"><h1>Give the facts<br><em>a useful meaning.</em></h1><p class="lead">Build a small knowledge system. Explain its conclusions. Measure its mistakes.</p><div class="row"><span class="tag">2-hour class</span><span class="tag">Offline labs</span><span class="tag">Bright + dark</span></div><p class="muted">Our case: a campus lab assistant that must use evidence before it answers.</p></div><div class="knowledge-cover"><div class="claim"><small>Fact</small>Amina completed safety training.</div><div class="claim"><small>Rule</small>Enrolled, trained students may book a lab slot.</div><div class="verdict">What follows?<br>What is still missing?</div></div></div>',notes:'Official class 4 combines Book Sessions 5 and 6: knowledge representation, logical reasoning, performance computation, metrics, and emerging/generative AI. Use the fictional campus example throughout. Invite reasoning aloud. Every student can participate without an account or programming setup.'},
{title:'A route and a reason to act',kicker:'Reconnect to Session 3',html:()=>'<div class="grid two">'+quiz('recall')+panel('The connection','Session 3 represented where an agent can go. Session 4 represents what it knows and what conclusions its evidence supports.','dark')+'</div>'+note('Pair discussion: list one fact, one rule, and one unanswered question for a helpful campus assistant.'),notes:'3 minutes. Sample fact: Lab 2 closes at 17:00. Rule: completed safety training is required. Question: does a named student have a valid record? Explain that rules can constrain planning. Knowledge can include a map, so the approaches connect.'},
{title:'The route through this class',kicker:'120 minutes · meaning, experiments, and explanation',html:()=>'<div class="grid two"><div class="panel stack"><h3>By the end you can…</h3><ul><li>Represent facts, relationships, and rules.</li><li>Explain deduction and its assumptions.</li><li>Read simple Boolean Python code.</li><li>Compute and interpret basic metrics.</li><li>Check a generated answer against evidence.</li></ul></div><div class="panel agenda04">'+sections.map((s,i)=>'<div class="agenda-row"><span>'+String(i+1)+'</span><button data-go="'+s.start+'">'+s.name+'</button><span class="time">'+s.time+' min</span></div>').join('')+'</div></div>',notes:'Run a 120-minute class: 10 reconnect, 20 representation, 10 knowledge cycle, 20 logic, 15 Python, 25 metrics, 10 emerging AI, 10 practice. Invite predictions before every reveal. Detailed downloads support further practice rather than adding new prerequisites during class.'},
{title:'The campus assistant’s task',kicker:'A familiar problem with missing information',html:()=>'<div class="grid two">'+panel('Amina asks…','“Can I enter Lab 2, and when is it open?”','dark')+'<div class="panel stack"><h3>What would you need?</h3><ul><li>Opening hours and their source.</li><li>Amina’s enrolment and training status.</li><li>A clear access policy.</li><li>A way to handle unknown or changed records.</li></ul></div></div>'+note('Students play the assistant. The teacher plays Amina and reveals only the facts they ask for.'),notes:'3 minutes. Use the role-play before definitions. The policies are fictional and deliberately simplified. Knowing opening hours does not establish a particular person’s eligibility. Ask what happens when a record is outdated.'},
{title:'Data, information, and knowledge',kicker:'Why representation needs meaning',html:()=>'<div class="grid three">'+panel('Data','“Amina, 1, 2026-11-01” is a collection of values. We need labels to interpret them.')+panel('Information','“Amina completed safety training on 1 November” gives the values context.')+panel('Knowledge','An explicit fact plus an access rule lets the assistant reason about a relevant decision.')+'</div>'+panel('Knowledge and intelligence','Knowledge supplies content. Useful intelligent behaviour also needs ways to reason, learn, plan, and act. The quality and relevance of the content affect the result.')+note('A large collection of facts does not, by itself, specify how to use them.'),notes:'2 minutes. Treat these as useful teaching distinctions, not a universal rigid hierarchy. A knowledge representation makes meaning usable by a system. Wrong facts plus correct inference can still yield wrong real-world advice.'},
{title:'Types of knowledge',kicker:'Interactive examples with different purposes',html:()=>'<div class="tabs04">'+Object.entries(knowledgeTypes).map(([k,v])=>'<button data-knowledge-type="'+k+'" aria-pressed="'+(state.knowledgeType===k)+'">'+v[0].replace(' knowledge','')+'</button>').join('')+'</div><div id="knowledgeDetail" class="panel stack detail04" aria-live="polite">'+typeHTML()+'</div>'+note('Challenge: “Check the booking register before suggesting a slot.” Which kind of knowledge is it, and why?'),notes:'3 minutes. The challenge describes a procedure. Heuristics are helpful but defeasible. Meta-knowledge can include provenance and confidence. Categories overlap. The manual requests types but does not supply its exact textbook taxonomy, so these common examples are supplements.'},
{title:'Approaches to representation',kicker:'The format should serve the task',html:()=>'<table class="small-table"><thead><tr><th>Approach</th><th>What it makes explicit</th><th>Campus example</th></tr></thead><tbody><tr><td>Logic and rules</td><td>Claims and conditions for conclusions</td><td>Training and enrolment imply eligibility</td></tr><tr><td>Semantic networks</td><td>Entities and labelled relationships</td><td>Lab 2 is part of a building</td></tr><tr><td>Frames</td><td>Attributes grouped around an entity</td><td>A student record with named slots</td></tr><tr><td>Ontologies</td><td>Shared concepts, relations, and constraints</td><td>Student, room, course, enrolled-in</td></tr><tr><td>Probabilistic representations</td><td>Uncertainty and dependencies</td><td>Uncertain room occupancy</td></tr><tr><td>Learned numerical representations</td><td>Patterns encoded as vectors</td><td>Find related handbook passages</td></tr></tbody></table>'+note('A system can combine formats. Clear rules support traceable decisions. Vectors can support similarity search, but similarity alone does not prove a claim.'),notes:'3 minutes. Briefly define ontology as shared vocabulary and relationships with constraints. Distinguish a semantic network example from a richer ontology. Probabilistic models may encode beliefs under uncertainty. Learned representations are not interchangeable with explicit symbolic proof.'},
{title:'The same fact in different forms',kicker:'Interactive representation lab',html:()=>'<p class="lead">Amina is enrolled and has completed safety training.</p><div class="tabs04">'+Object.entries(representations).map(([k,v])=>'<button data-representation="'+k+'" aria-pressed="'+(state.representation===k)+'">'+v[0]+'</button>').join('')+'</div><div id="representationDetail" class="panel stack detail04" aria-live="polite">'+representationHTML()+'</div>'+note('Explain which format helps you look up an attribute, follow a relationship, or derive a conclusion.'),notes:'3 minutes. A fact and a rule serve different roles. The rule tab is a policy to apply, not an alternative encoding of the same specific fact. Make this distinction explicit after students compare the displays. Frames resemble records or dictionaries.'},
{title:'Relationships in a semantic network',kicker:'The edge label changes the meaning',html:()=>'<div class="semantic-list"><div class="relation04"><button data-relation="Amina">Amina</button><span>is an instance of</span><button data-relation="Student">Student</button></div><div class="relation04"><button data-relation="Lab2">Lab 2</button><span>is part of</span><button data-relation="Building">Science building</button></div><div class="relation04"><button data-relation="Student">Student</button><span>may enrol in</span><button data-relation="Course">Course</button></div></div><div id="relationDetail" class="feedback" aria-live="polite">Select an entity or concept to explain its role.</div>'+note('“Is a kind of”, “is an instance of”, and “is part of” mean different things. A lab is part of a building, rather than a kind of building.'),notes:'2 minutes. Click each named item. Explain concept versus individual. A labelled relation makes structure meaningful. Inheritance applies only under appropriate definitions and rules. Do not infer that every attribute of a whole belongs to every part.'},
{title:'Missing information has a meaning',kicker:'True, False, and Unknown',html:()=>'<div class="grid two">'+quiz('unknown')+'<div class="panel stack"><h3>A student frame</h3><div class="fact-value">enrolled: True</div><div class="fact-value">completed_safety: Unknown</div><p>The assistant should request the missing training record before recommending entry.</p></div></div>'+note('Some databases deliberately assume an unrecorded fact is false. That is a chosen closed-world assumption. It must fit the task.'),notes:'4 minutes. Contrast explicit false with absence. The knowledge lab uses three-valued conjunction. Classical logic slides use two truth values. Real systems can have contradictory evidence as well, which this simple lab does not model. A closed-world assumption can suit a complete booking database but not arbitrary missing records.'},
{title:'The knowledge cycle',kicker:'Evidence must stay connected to the world',html:()=>'<div class="cycle04"><div><b>Acquire</b>Collect records or observations.</div><div><b>Check</b>Inspect source, relevance, and date.</div><div><b>Represent</b>Store meaningful facts and relationships.</div><div><b>Reason</b>Apply supported rules.</div><div><b>Plan</b>Choose actions to reach a goal.</div><div><b>Decide</b>Compare permitted options and costs.</div><div><b>Act</b>Perform or recommend an action.</div><div><b>Update</b>Check outcomes and refresh records.</div></div>'+note('Example: a new suspension record changes the facts. Recompute conclusions that depended on the old record.'),notes:'2 minutes. Present the cycle as a teaching model of a knowledge-based system, not a required universal implementation. Acquisition can include learning. Connect updates to Session 3’s stale robot memory. Sources and dates help identify facts that need revision.'},
{title:'Facts become conclusions',kicker:'Interactive rule trace · predict each step',html:rulesHTML,notes:'5 minutes. Start with enrolled=True, completed_safety=True, suspended=False. Ask predictions before each of 3 rules: trained=True, eligible=True, may_enter=True. Change completed_safety to Unknown and re-run: insufficient evidence. Change suspended to True: may_enter=False. A false condition can determine an AND even when another is unknown. Changes reset the trace and recompute from current facts, avoiding stale derived conclusions. This three-valued evaluation is an explicit teaching model, not a generic theorem prover.'},
{title:'Knowledge supports planning and decisions',kicker:'A goal, permitted actions, and a preference',html:()=>'<div class="grid three">'+panel('Knowledge','The student is eligible. Lab 2 has a free slot. Lab 1 is closed.')+panel('Planning','Choose a sequence: select the Lab 2 slot, request a booking, wait for confirmation.')+panel('Decision-making','If two permitted slots exist, compare the student’s stated preference or travel time.')+'</div>'+note('A plan must respect the current facts. A suggestion does not prove that a booking succeeded. Confirm the outcome.'),notes:'2 minutes. Tie planning to search in Session 3. Knowledge supplies states, actions, and constraints. A decision needs an objective or preference. Show that eligibility, availability, preference, and completed booking are different claims.'},
{title:'When the evidence changes',kicker:'A conclusion needs its supporting facts',html:()=>'<div class="grid two">'+panel('Earlier record','Amina’s training was complete and suspension was False. The access rule was satisfied.','green')+panel('New record','A current suspension record says True. Re-evaluate the dependent conclusion before recommending entry.','soft')+'</div><div class="worksheet">'+field('knowledgeUpdate','Which conclusion changes, and which fact causes the change?','Explain the dependency rather than just saying “access changes”.')+'</div>'+note('Partner challenge: choose one missing fact that would force the assistant to ask a follow-up question.'),notes:'1 minute. Expected: may_enter becomes False because NOT suspended becomes False. Earlier eligibility may remain True, so explain why not every derived fact necessarily changes. Invite a missing enrolment or training record as a follow-up case.'},
{title:'What logical reasoning does',kicker:'Premises, rules, and conclusions',html:()=>'<div class="grid three">'+panel('Premises','Statements we use as starting points: Amina completed safety training.')+panel('Rule','If a student completed safety training, that student is trained.')+panel('Conclusion','Under that fact and rule, Amina is trained.')+'</div>'+note('A valid deduction preserves truth if its premises are true. It does not independently verify that the starting records match the world.'),notes:'2 minutes. Define inference as deriving a conclusion from premises. Explain valid reasoning versus reliable evidence. A mistaken training record can lead a logically valid rule application to a false real-world conclusion.'},
{title:'Deduction, induction, and abduction',kicker:'Different kinds of support',html:()=>'<div class="reasoning-cards">'+panel('Deduction','Apply a general rule to known facts. If all trained students may book, and Amina is trained, she may book under that rule.')+panel('Induction','Generalise from examples. After many busy Fridays, predict that the next Friday may also be busy.')+panel('Abduction','Suggest an explanation for an observation. A wet courtyard may suggest rain, but other causes are possible.')+'</div>'+note('Deduction can guarantee a conclusion under true premises and valid rules. Inductive predictions and abductive explanations can be wrong.'),notes:'3 minutes. Ask students to invent one example per type. Induction supports learning patterns. Abduction seeks plausible explanatory hypotheses. Do not equate “best explanation” with certainty or imply one observation alone establishes a general law.'},
{title:'Reasoning under uncertainty and exceptions',kicker:'A rule of thumb needs a limit',html:()=>'<div class="grid two">'+panel('Probabilistic reasoning','Represent uncertainty, then update beliefs when new evidence arrives. A probability depends on the model and evidence.')+panel('Default reasoning','Use a provisional assumption with exceptions, such as “the lab follows normal weekday hours unless a closure notice applies”.')+'</div>'+note('New evidence can overturn a default. A likely conclusion needs a different explanation from a deductive proof.'),notes:'2 minutes. Introduce probabilistic and non-monotonic/default reasoning at overview level. A probability needs support rather than an invented certainty. A new closure notice can defeat a normal-hours default. Avoid extra probability calculations in this short block.'},
{title:'A deductive conclusion',kicker:'Quick check · explain what follows',html:()=>'<div class="grid two">'+quiz('deduction')+panel('The boundaries of the claim','Permission to book, an actual booking, and every student’s training status are separate statements. A valid conclusion should stay within the given premises.','dark')+'</div>',notes:'2 minutes. Correct: Amina may book a practice slot under the given policy. Ask which premise would need to change for the conclusion to fail. Use the explicit policy rather than an unstated real campus policy.'},
{title:'Propositional logic',kicker:'Statements with truth values',html:()=>'<div class="grid two"><div class="panel stack"><h3>Short names for whole statements</h3><p>P: Amina is enrolled.<br>Q: Amina completed safety training.</p><pre class="code">P ∧ Q     both statements hold\nP ∨ Q     at least one holds\n¬P        P does not hold\nP ⇒ Q     if P, then Q</pre></div>'+panel('Why use symbols?','A compact form makes a rule’s structure precise. First understand the statement behind each symbol, then manipulate its form.')+'</div>'+note('“OR” here includes the case where both statements are true. An implication has a direction.'),notes:'2 minutes. Explain proposition as a statement evaluated true/false in this model. Distinguish a statement from a command or question. Symbols are names for logical structure, not decoration. P⇒Q is the material implication connective, not proof of a physical cause.'},
{title:'A truth table you can change',kicker:'Interactive Boolean logic lab',html:logicHTML,notes:'4 minutes. Toggle P/Q, then compare AND, inclusive OR, NOT, implication. The implication fails exactly when P=True,Q=False. For P=False it is true regardless of Q, which does not prove either premise or a causal relation. NOT ignores Q. This two-valued lab is intentionally separate from the unknown-fact lab.'},
{title:'Predicate logic and named entities',kicker:'One property, many possible people',html:predicateHTML,notes:'3 minutes. Explain x as a placeholder for a person in a defined domain. ∀ means every member, ∃ means at least one. Initially all=False and exists=True. One counterexample defeats “all”. One witness establishes “exists”. Domain choice matters. A closed three-person roster is a deliberate simplification.'},
{title:'A consequence does not prove its cause',kicker:'Reasoning trap · test another explanation',html:()=>'<div class="grid two">'+quiz('reverse')+'<div class="panel proof-pair"><div class="stack"><h3>Valid: modus ponens</h3><pre class="code">P ⇒ Q\nP\nTherefore Q</pre></div><div class="stack"><h3>Invalid reverse</h3><pre class="code">P ⇒ Q\nQ\nTherefore P\n(not guaranteed)</pre></div></div></div>'+note('Act it out: rain, sprinkler, and cleaner can each explain a wet courtyard. Ask what evidence would distinguish the causes.'),notes:'2 minutes. Correct: wet does not prove rain. Call the reverse error affirming the consequent if students want the name. A rule is not a biconditional unless both directions are specified. Rain might still be an abductive hypothesis.'},
{title:'Python can encode a simple decision',kicker:'Bridge from rules to code',html:()=>'<div class="grid two"><div class="panel stack"><h3>The fictional policy</h3><p>Access requires enrolment, completed safety training, and an explicit record of no suspension.</p><pre class="code">enrolled AND completed_safety\nAND NOT suspended</pre></div><div class="panel stack"><h3>Python foundations</h3><ul><li>A variable names a stored value.</li><li>True and False are Boolean values.</li><li>and combines required conditions.</li><li>not reverses a Boolean condition.</li><li>if selects a branch of instructions.</li></ul></div></div>'+note('The next example uses only verified Boolean inputs. Unknown needs explicit handling, as in the knowledge lab.'),notes:'3 minutes. Python True/False use capital letters. Lowercase true is a name, not the built-in Boolean literal. A variable is not a magic keyword: choose a meaningful valid name. Strings use quotes, Boolean values do not. The code is a small rule-based decision, not a trained model.'},
{title:'Predict, edit, and run the rule',kicker:'Beginner code lab · change one fact',html:()=>'<div class="lab04"><div class="stack"><label for="codeEditor">Start by predicting both output lines:</label><textarea id="codeEditor" class="editor code04" spellcheck="false" autocapitalize="off">'+esc(state.code)+'</textarea><div class="row"><button id="runCode" class="accent">Run rule example</button><button id="restoreCode">Restore example</button></div><p class="caption">Limited teaching interpreter: Boolean variables, and/or/not, parentheses, if/else, and print. Use spaces for indentation. A full Python file is available below.</p></div><div class="stack"><h3>Output</h3><div id="codeOutput" class="console" aria-live="polite">'+esc(state.codeOutput||'What will may_enter contain? Which message will print?')+'</div>'+panel('Try one change','Set completed_safety to True. Then try suspended = True. Explain which part of the condition changes the result.')+'<a href="knowledge_rules.py" download class="small">Download the real Python rule example</a></div></div>',notes:'5 minutes. Initial output: False, then Check requirements. With completed_safety=True and no suspension, output True, Lab access granted. With suspended=True, not suspended=False, so access False. Browser code implements a restricted teaching subset, not a complete Python runtime. Real Python downloads need Python installed. Help students fix indentation and case errors by reading the reported line.'},
{title:'Why each line has that form',kicker:'Interactive line-by-line explanation',html:()=>'<div class="line-buttons04">'+codeLines.map((_,i)=>'<button data-code-line="'+i+'" aria-pressed="'+(i===0)+'">Line '+(i+1)+'</button>').join('')+'</div><div id="lineDetail" class="panel stack detail04"><pre class="line04">'+esc(codeLines[0][0])+'</pre><p>'+codeLines[0][1]+'</p></div>'+note('Explain the equals sign, quotation marks, colon, indentation, and parentheses to a partner. Those symbols each have a job.'),notes:'4 minutes. Click lines 4, 6, 7, 8 especially. Assignment uses =. Equality comparison uses ==, though this example does not need it. A colon begins a block, indentation defines membership, and else names the alternative branch. Python evaluates the assigned Boolean expression before if uses the value. Underscores keep a multiword name together.'},
{title:'Make a small, justified change',kicker:'Code assignment · predict before running',html:()=>'<div class="grid two">'+panel('Your task','Make the program reject a student who is enrolled and trained but suspended. Then make it accept the same student after the suspension is explicitly cleared.','dark')+'<div class="worksheet">'+field('codePrediction','Write the two predicted outputs and explain the changed condition.','What does not suspended evaluate to in each case?')+field('codeMeaning','Why is the message inside the if block indented?','Explain which branch Python should execute.')+'</div></div><button class="primary" data-go="23">Return to the code lab</button>',notes:'3 minutes. With suspended=True: False/Check requirements. With suspended=False and other inputs True: True/Lab access granted. Indentation makes the print call part of the selected block. Grade the explanation, not merely matching output. Do not add new syntax before students explain the existing code.'},
{title:'A useful system needs a measure of success',kicker:'Performance computation and analysis',html:()=>'<div class="grid two">'+panel('Choose the task','Our second case is a spam filter. “Positive” means the filter flags a message as spam.')+panel('Define the evidence','Compare its prediction with a trusted label for messages it did not train on.')+'</div>'+note('A wrong spam flag can hide a legitimate message. A missed spam message reaches the inbox. Different mistakes may have different costs.'),notes:'3 minutes. Explain ground truth as the evaluation labels, not an infallible universal fact. Clarify the positive class before calculating. A representative labelled evaluation set should reflect intended use. Counts and mistake types provide evidence before one summary number.'},
{title:'Four outcomes in a confusion matrix',kicker:'Actual label compared with prediction',html:()=>'<div class="grid two"><table class="small-table"><thead><tr><th></th><th>Actually spam</th><th>Actually normal</th></tr></thead><tbody><tr><th>Flagged spam</th><td>TP: spam caught</td><td>FP: normal wrongly flagged</td></tr><tr><th>Kept normal</th><td>FN: spam missed</td><td>TN: normal correctly kept</td></tr></tbody></table><div class="panel stack"><h3>Meaning of the names</h3><p>True / false says whether the prediction was correct.</p><p>Positive / negative says whether the system predicted the chosen positive class.</p></div></div>'+note('Human sorting game: label four paper messages with their actual class and prediction. Place each in its matrix cell.'),notes:'3 minutes. TP actual spam/predicted spam. FP normal/spam. FN spam/normal. TN normal/normal. Students often confuse FP with FN, so ask which class the model predicted. Rows/columns in different libraries may differ, so always read axis labels.'},
{title:'Change the threshold and inspect the mistakes',kicker:'Interactive performance lab',html:metricsHTML,notes:'8 minutes. At 0.50: TP3, FP2, FN1, TN6. Accuracy9/12=75%, precision3/5=60%, recall3/4=75%, F1=6/9≈66.7%. At .35: TP4 FP3 FN0 TN5. At .80: TP2 FP0 FN2 TN8. At threshold1 all scores are lower, so nothing is flagged. Baseline always-normal produces accuracy66.7%, recall0%, undefined precision. A score need not equal a calibrated probability. This tiny invented set teaches arithmetic and trade-offs, not production threshold selection.'},
{title:'Accuracy, precision, recall, and F1',kicker:'The denominator tells you the question',html:()=>'<div class="grid two formula-list04">'+panel('Accuracy','<span class="metric-formula04">(TP + TN) / all messages</span><br>How often were we correct overall?')+panel('Precision','<span class="metric-formula04">TP / (TP + FP)</span><br>Of everything flagged, how much was spam?')+panel('Recall','<span class="metric-formula04">TP / (TP + FN)</span><br>Of all real spam, how much did we catch?')+panel('F1 score','<span class="metric-formula04">2TP / (2TP + FP + FN)</span><br>The harmonic mean of precision and recall. It leaves true negatives out.')+'</div>'+note('If a denominator is zero, that ratio is undefined. Software may use a chosen convention. State the convention when you report it.'),notes:'4 minutes. Students point at the denominator and say what group it counts. F1 is not the ordinary arithmetic mean and is not automatically the best objective. With no predicted positives precision is undefined. Count-based F1 is zero when positive examples exist but TP is zero, and undefined if TP=FP=FN=0. The lab visibly marks zero-denominator cases.'},
{title:'High accuracy can hide a failed task',kicker:'Class imbalance and a simple baseline',html:()=>'<div class="grid two">'+quiz('accuracy')+panel('A 100-message example','95 messages are normal and 5 are spam. “Always normal” gets 95 correct while catching none of the spam.','dark')+'</div>'+note('Compare against a simple baseline, report class counts, and inspect the types of errors. A large accuracy number alone cannot answer every task question.'),notes:'3 minutes. Distinguish this static 100-message example from the 12-message lab. Positive spam recall is 0/5. Precision is undefined because predicted positives are zero. Class balance in deployment can change measured precision and accuracy.'},
{title:'Choosing metrics and evaluating fairly',kicker:'Match the measure to the task',html:()=>'<div class="evaluation04">'+panel('Classification','Inspect precision, recall, F1, and error costs. Choose a threshold on validation data, then evaluate once on held-out test data.')+panel('Number prediction','MAE averages absolute errors. RMSE squares errors before averaging and taking a square root, so large errors count more.')+panel('System performance','Measure latency, cost, and task completion too. A useful answer must arrive in a useful time and fit the task.')+'</div>'+note('Example MAE: actual [10, 20], predicted [12, 17]. Absolute errors [2, 3], so MAE = 2.5 in the target’s units.'),notes:'3 minutes. Explain held-out data as examples kept separate from training and tuning. Do not repeatedly select a threshold using the final test set. MAE=(2+3)/2=2.5, RMSE=sqrt((4+9)/2)≈2.55. R² compares squared errors with a mean baseline and can be negative. ROC-AUC evaluates score ranking across thresholds and can hide positive-class issues under imbalance, so use PR analysis as appropriate. These optional overview terms belong in the word bank, with detailed computation deferred.'},
{title:'Compute and explain one result',kicker:'Metrics assignment · show the denominator',html:()=>'<div class="grid two"><div class="panel stack"><h3>At threshold 0.50</h3><p>TP = 3, FP = 2, FN = 1, TN = 6.</p><p>Calculate accuracy, precision, recall, and F1. Then explain which mistake you would inspect first and why.</p><button data-go="28" class="primary">Check against the metrics lab</button><a href="performance_metrics.py" download class="small">Download the commented Python calculation</a></div><div class="worksheet">'+field('metricsMath','Write each formula with numbers substituted.','Show which group the denominator counts.')+field('metricChoice','Would you lower or raise the threshold? Explain a trade-off.','What is the cost of an extra false flag compared with a missed spam message?')+'</div></div>',notes:'1-minute launch, complete during self-study. Answers: accuracy75%, precision60%, recall75%, F1≈66.7%. Raising threshold generally reduces flags and may miss more positives in this fixed set. Lowering catches more spam but can flag more normal messages. Precision need not improve monotonically with threshold on every dataset. Accept reasoned objectives rather than one universally preferred threshold.'},
{title:'Emerging directions in AI',kicker:'Connect new capabilities to the foundations',html:()=>'<div class="grid two">'+panel('Generative and multimodal systems','Generate text, images, audio, or other content. Multimodal systems can combine different input or output forms.')+panel('Retrieval with generation','Find relevant source material, then use it to help compose an answer. Check that each important claim has support.')+panel('Agents with tools','A system may plan actions and use software tools. Permissions, feedback, and outcome checks matter.')+panel('Smaller models and local inference','Some tasks run on local devices to meet latency, privacy, or resource needs. Suitability depends on the task and model.')+'</div>'+note('These directions connect to learned representations, search, knowledge, planning, and evaluation. New capability still needs a well-defined task.'),notes:'2 minutes. Present examples as directions rather than ranked or exhaustive trends. Do not assert human-level intelligence. Multimodal may involve text/image inputs without generating every modality. Local inference does not automatically ensure privacy of every surrounding application. Sources: NIST GenAI Profile for evidence/error considerations.'},
{title:'What generative AI produces',kicker:'Generation and evidence answer different needs',html:()=>'<div class="grid two">'+panel('Generation','A language model learns patterns and generates token sequences from its context. A token is a piece of text and may be part of a word.')+panel('Evidence','An answer about current campus hours needs a relevant current source. A fluent generated sentence can still contain a false claim.','soft')+'</div>'+note('Generative AI can help draft an explanation or practice question. For factual advice, check the claim, its source, and what the source leaves unknown.'),notes:'3 minutes. Explain hallucination/confabulation as confidently presented false or unsupported content. A model’s generation is not the same thing as a symbolic proof. NIST AI600-1 discusses confabulation. Do not imply every false generated statement is intentional or that citation text automatically proves a source exists.'},
{title:'An answer with evidence to inspect',kicker:'Interactive, scripted grounding comparison',html:generativeHTML,notes:'5 minutes. Start with the hours question and supplied-facts box checked. It quotes 09:00–17:00 weekdays from F1. Uncheck to show the intentionally unsupported 08:00 claim. Ask which word in the source contradicts “every day”. Fee question with evidence enabled should report that no fee is stated. Explain retrieval-augmented generation as retrieving relevant content before generating, while this offline demo is only scripted and performs no actual retrieval or model call. Retrieval reduces some risks but does not guarantee correctness.'},
{title:'Build your own small knowledge assistant',kicker:'Practical assignment · facts, rules, and questions',html:()=>'<div class="grid two"><div class="panel stack"><h3>Your scenario</h3><p>Choose a library loan, event registration, or equipment booking assistant.</p><ol><li>Record 4 facts with meaningful labels.</li><li>Choose a frame, relationships, or logic.</li><li>Write 2 rules and explain their conclusions.</li><li>Include an unknown fact and an update.</li><li>Explain one useful performance measure.</li></ol></div><div class="worksheet">'+field('ownKnowledge','Your facts, representation, and two rules','Separate facts about one case from rules that apply to cases.')+field('ownUnknown','Your unknown fact and follow-up question','What evidence would resolve it?')+'</div></div>',notes:'4-minute launch. Example library case: member=True, overdue=False, item_available=True, loan_limit_reached=False. Rules: valid_member and no overdue → eligible; eligible and item_available → may_request. Unknown availability prompts a stock check. Do not treat a request as a completed loan. Rubric: clear relevant facts3, representation2, justified rules2, unknown/update2, suitable metric1. Full implementation can be a stretch task.'},
{title:'Self-study with a visible result',kicker:'S2 · the remaining 80 minutes',html:()=>'<div class="grid two"><div class="panel stack self-study04"><h3>80-minute practice plan</h3><ul><li>20 min: improve your knowledge assistant and trace a changed fact.</li><li>20 min: run the real Python rule file and explain each line.</li><li>25 min: compare three thresholds and calculate metrics.</li><li>15 min: check a factual generated answer against supplied evidence.</li></ul></div><div class="panel stack"><h3>What you submit</h3><p>Your facts and rules, a code prediction and result, metric calculations, and an evidence check.</p><p class="caption">Session 3 assigned the first 40 minutes of S2. This completes the 120-minute S2 block.</p><button id="downloadWork" class="primary">Download my worksheet</button><div class="save-status04" id="saveStatus">'+(save()?'Answers save in this browser. Download a copy for submission.':'Browser storage is unavailable. Download your answers before closing.')+'</div></div></div>',notes:'2 minutes. S2 totals 2 hours:40 minutes after class3 and80 after class4. These original supplemental tasks do not claim to reproduce ProConnect assignments or textbook questions. Map official homework separately if available. No paid API is needed. Students who lack Python can complete browser predictions and paper trace work first.'},
{title:'Exit ticket: meaning before memorisation',kicker:'Quick checks with explanations',html:()=>'<div class="grid two"><div class="stack">'+quiz('exit1')+quiz('exit2')+'</div>'+quiz('exit3')+'</div>',notes:'3 minutes. Frame slots, precision denominator, and evidence limits. Ask students to explain their choice without repeating button wording. If a large group misses a question, revisit the corresponding demonstration. This is formative feedback rather than a high-stakes exam.'},
{title:'Your foundations are now connected',kicker:'Next class · OpenAI coding in Python',html:()=>'<div class="grid two"><div class="panel dark stack"><h3>Explain the whole system</h3><p>Represent relevant facts. Apply justified rules. Choose actions. Measure outcomes. Check the evidence behind an answer.</p><p class="muted">Next: use these foundations when working with model prompts and Python API calls.</p></div><div class="worksheet">'+field('exitWhy','Why does an AI assistant need both a useful representation and a way to evaluate its answers?','Give one example from today’s labs.')+'<div class="row"><button id="downloadFinal" class="primary">Download my work</button><button id="sourcesBtn">Sources and coverage</button></div><div class="portfolio"><a href="knowledge_rules.py" download>Python rules</a><a href="performance_metrics.py" download>Python metrics</a></div></div></div>'+note('Carry one habit forward: explain why each fact, rule, line of code, and metric is needed.'),notes:'1 minute. Session5 follows Book7: OpenAI coding in Python. The manual names older model examples, so verify current model availability and API documentation before that session. Today requires no external model, API key, or account. Wrap up with a student explanation of how representation and evaluation prevent specific errors.'}
];
const codeLines=[['enrolled = True','Create the variable enrolled and assign the Boolean value True. The single equals sign stores a value. It does not ask whether two values are equal.'],['completed_safety = False','Store a verified False input for this example. The underscore makes a readable single variable name. Missing information would need its own explicit handling.'],['suspended = False','Store an explicit record that the student is not suspended. Avoid assuming this value merely because no record was found.'],['may_enter = enrolled and completed_safety and not suspended','Evaluate the condition and store its result. and requires all conditions to hold. not suspended reverses the Boolean suspension value.'],['print(may_enter)','Call the print function with the variable’s current value. Parentheses enclose the argument. No quotes means inspect the variable, rather than display its name as text.'],['if may_enter:','If the stored condition is true, execute the indented block. The colon starts the block. The expression was evaluated earlier when may_enter was assigned.'],['    print("Lab access granted")','Four leading spaces place this instruction inside the if block. Quotes make the message a text string. It executes only when the if condition holds.'],['else:','Choose the alternative block when the if condition is false. else aligns with its if. The colon again begins the indented block.'],['    print("Check requirements")','This indented message belongs to else. The program prints it when at least one required Boolean condition fails.']];
// The teaching interpreter parses a small Python subset. It never evaluates JavaScript source.
function runTeachingCode(source){
  const env=Object.create(null),output=[];
  function tokenize(s,n){const tokens=[];let pos=0;while(pos<s.length){const rest=s.slice(pos),m=rest.match(/^(\s+|"[^"\\]*"|'[^'\\]*'|[A-Za-z_]\w*|[()])/);if(!m)throw Error('Line '+n+': unsupported expression. Use Boolean names, and/or/not, parentheses, or simple quoted text.');pos+=m[0].length;if(!/^\s+$/.test(m[0]))tokens.push(m[0]);}return tokens;}
  function expression(s,n){const ts=tokenize(s,n);let i=0;const at=()=>ts[i];function atom(){const t=ts[i++];if(t==='('){const node=or();if(ts[i++]!==')')throw Error('Line '+n+': missing closing parenthesis.');return node;}if(t==='True'||t==='False')return {value:t==='True'};if(t&&/^['"]/.test(t))return {value:t.slice(1,-1)};if(t&&/^[A-Za-z_]\w*$/.test(t)&&!['and','or','not'].includes(t))return {name:t};throw Error('Line '+n+': expected a Boolean value or variable name.');}function neg(){if(at()==='not'){i++;return {op:'not',right:neg()};}return atom();}function and(){let node=neg();while(at()==='and'){i++;node={op:'and',left:node,right:neg()};}return node;}function or(){let node=and();while(at()==='or'){i++;node={op:'or',left:node,right:and()};}return node;}const ast=or();if(i!==ts.length)throw Error('Line '+n+': unexpected token '+ts[i]+'.');function bool(v){if(typeof v!=='boolean')throw Error('Line '+n+': this teaching subset requires Boolean conditions (True or False).');return v;}function evaluate(a){if(Object.hasOwn(a,'value'))return a.value;if(a.name){if(!Object.hasOwn(env,a.name))throw Error('Line '+n+': NameError — '+a.name+' has not been assigned.');return env[a.name];}if(a.op==='not')return !bool(evaluate(a.right));const l=bool(evaluate(a.left));return a.op==='and'?(l?bool(evaluate(a.right)):false):(l?true:bool(evaluate(a.right)));}return evaluate(ast);}
  try{if(source.length>12000)throw Error('Keep this exercise under 12,000 characters.');const lines=source.replace(/\r/g,'').split('\n').map((raw,i)=>{if(raw.includes('\t'))throw Error('Line '+(i+1)+': use spaces rather than tabs in this teaching subset.');const indent=raw.match(/^ */)[0].length;return {text:raw.trim(),indent,n:i+1};}).filter(l=>l.text&&!l.text.startsWith('#'));if(lines.length>100)throw Error('Keep this exercise under 100 instructions.');let cursor=0;function block(indent,execute){let count=0;while(cursor<lines.length){const l=lines[cursor];if(l.indent<indent||l.text==='else:')break;if(l.indent>indent)throw Error('Line '+l.n+': unexpected indentation.');cursor++;count++;const ifMatch=l.text.match(/^if\s+(.+):$/);if(ifMatch){const value=execute?expression(ifMatch[1],l.n):false;if(execute&&typeof value!=='boolean')throw Error('Line '+l.n+': if requires a Boolean value in this teaching subset.');if(!lines[cursor]||lines[cursor].indent!==indent+4)throw Error('Line '+l.n+': indent the if block by four spaces.');block(indent+4,execute&&value);if(lines[cursor]?.text==='else:'&&lines[cursor].indent===indent){const e=lines[cursor++];if(!lines[cursor]||lines[cursor].indent!==indent+4)throw Error('Line '+e.n+': indent the else block by four spaces.');block(indent+4,execute&&!value);}continue;}const assignment=l.text.match(/^([A-Za-z_]\w*)\s*=\s*(?!=)(.+)$/),print=l.text.match(/^print\((.*)\)$/);if(assignment){if(['True','False','and','or','not','if','else','print'].includes(assignment[1]))throw Error('Line '+l.n+': choose a variable name that is not a reserved teaching word.');if(execute)env[assignment[1]]=expression(assignment[2],l.n);}else if(print){if(execute){const v=expression(print[1],l.n);output.push(typeof v==='boolean'?truth(v):String(v));}}else throw Error('Line '+l.n+': unsupported instruction. Use assignment, if/else, or print.');}return count;}block(0,true);if(cursor<lines.length)throw Error('Line '+lines[cursor].n+': else needs a matching if at the same indentation.');return output.length?output.join('\n'):'No output. Add print() to inspect a value.';}catch(e){return (output.length?output.join('\n')+'\n':'')+e.message;}
}
const glossary=[['Knowledge representation','A format that makes relevant facts, relationships, rules, or beliefs usable by a system.'],['Knowledge base','A collection of represented knowledge that a system can use.'],['Declarative knowledge','Facts or claims about a situation.'],['Procedural knowledge','Instructions or methods for performing a task.'],['Heuristic','A useful rule of thumb or estimate that can have exceptions.'],['Meta-knowledge','Knowledge about knowledge, such as its source or how to apply it.'],['Semantic network','Entities or concepts connected by meaningful labelled relationships.'],['Frame','Named attributes grouped around an entity or situation.'],['Ontology','A shared definition of concepts, relations, and constraints in a domain.'],['Provenance','Where a claim came from and its relevant context.'],['Closed-world assumption','An explicit modelling assumption that unrecorded facts are false.'],['Inference','Deriving a conclusion from facts or premises using a rule.'],['Deduction','Reasoning that preserves truth under true premises and valid inference rules.'],['Induction','Generalising or predicting from observations, with uncertainty.'],['Abduction','Inferring a plausible explanation for observations.'],['Default reasoning','Using assumptions that may be withdrawn when exceptions appear.'],['Proposition','A complete statement treated as true or false in classical propositional logic.'],['Predicate','A property or relation whose truth depends on its arguments.'],['Domain','The set of entities over which a variable or quantifier ranges.'],['Universal quantifier ∀','A property holds for every member of the stated domain.'],['Existential quantifier ∃','At least one member of the stated domain has the property.'],['Boolean','A value with one of two possibilities: True or False.'],['Assignment =','Store a value under a variable name in Python.'],['Equality ==','Compare values for equality in Python.'],['Indentation','Leading spaces that define which Python statements belong in a block.'],['Confusion matrix','Counts of actual classes compared with predicted classes.'],['True positive','A correctly predicted positive, here spam caught.'],['False positive','A wrongly predicted positive, here a normal message flagged.'],['False negative','An actual positive missed by the prediction, here spam kept.'],['True negative','A correctly predicted negative, here a normal message kept.'],['Accuracy','(TP+TN)/all examples: proportion of correct predictions.'],['Precision','TP/(TP+FP): proportion of flagged examples that are truly positive.'],['Recall','TP/(TP+FN): proportion of actual positives that are caught.'],['F1 score','2TP/(2TP+FP+FN), equivalent to the harmonic mean of precision and recall when defined.'],['Threshold','A decision boundary applied to a score to select a predicted class.'],['Baseline','A simple reference method used for comparison.'],['Class imbalance','Unequal numbers of examples in different classes.'],['Validation set','Separate examples used to tune choices such as a threshold.'],['Test set','Held-out examples used for final evaluation after choices are fixed.'],['MAE','Mean absolute error: average magnitude of numeric prediction errors in target units.'],['RMSE','Root mean squared error: square errors, average, and take a square root. Large errors count more.'],['R²','1 minus squared-error ratio against a mean baseline. Can be negative and depends on the evaluation set.'],['ROC-AUC','Summary of a score’s positive/negative ranking across thresholds. Read alongside task and class balance.'],['Generative AI','Models that produce content such as text, images, or audio from learned patterns and context.'],['Token','A unit processed by a model, often a piece of text rather than a whole word.'],['Hallucination / confabulation','A generated claim that is false or unsupported, sometimes expressed confidently.'],['RAG','Retrieval-augmented generation: retrieve relevant source material to help compose an answer.'],['Grounding','Connecting an answer’s claims to relevant supporting evidence.'],['Multimodal','Working with more than one form of input or output, such as text and images.'],['Latency','Time taken to return a result.']];
const stage=document.getElementById('stage');let lastFocus=null,seconds=7200,timerRunning=false,timerInterval=null;
function go(i){state.slide=Math.max(0,Math.min(slides.length-1,Number(i)||0));save();render();window.scrollTo({top:0,behavior:'instant'});}
function render(){const i=state.slide,s=slides[i],sec=sectionFor(i);document.title='Session 04 · '+s.title;stage.innerHTML='<article class="slide session04"><div class="slide-head"><div class="section-label"><span class="rule"></span><span class="eyebrow">'+esc(s.kicker)+'</span></div>'+(i===0?'':'<h2>'+esc(s.title)+'</h2>')+'</div>'+s.html()+'</article>';document.getElementById('pageLabel').textContent=(i+1)+' / '+slides.length+' · '+sec.name;document.getElementById('prevBtn').disabled=i===0;document.getElementById('nextBtn').disabled=i===slides.length-1;document.getElementById('progressFill').style.width=((i+1)/slides.length*100)+'%';document.getElementById('progress').setAttribute('aria-valuenow',i+1);document.getElementById('progress').setAttribute('aria-valuemax',slides.length);if(i===11)updateRules();if(i===19)updateLogic();if(i===20)updatePredicates();if(i===28)updateMetrics();if(i===35&&state.genOutput)showGenerated();}
function showGenerated(){const a=groundedAnswer(state.genQuestion,state.grounded);state.genOutput=a.text;save();document.getElementById('genAnswer').textContent=a.text;document.getElementById('genAnswer').classList.toggle('unsupported',!a.supported);document.getElementById('genWhy').textContent=a.why;}
function downloadWork(){const labels={knowledgeUpdate:'Changed evidence and dependent conclusion',codePrediction:'Predicted code outputs',codeMeaning:'Meaning of indentation',metricsMath:'Metric calculations',metricChoice:'Threshold trade-off',ownKnowledge:'Own assistant facts, representation, and rules',ownUnknown:'Unknown fact and follow-up question',exitWhy:'Why representation and evaluation matter'};const pieces=['FOUNDATIONS OF AI · SESSION 04','Student worksheet · '+new Date().toLocaleDateString(),''];for(const [k,label] of Object.entries(labels))pieces.push(label+'\n'+(state.worksheet[k]||'[Not answered]')+'\n');pieces.push('MY RULE CODE\n'+state.code,'LAST TEACHING-INTERPRETER OUTPUT\n'+(state.codeOutput||'[Not run]'),'KNOWLEDGE LAB FACTS\n'+JSON.stringify(state.facts),'CURRENT RULE CONCLUSIONS\n'+knowledgeTrace(state.facts).map(t=>t.name+': '+truth(t.value)).join('\n'),'METRICS LAB\nMode: '+(state.baseline?'always normal':'threshold '+state.threshold/100)+'\n'+JSON.stringify(metricsAt(state.threshold,state.baseline)),'SCRIPTED EVIDENCE CHECK\n'+(state.genOutput||'[Not run]'),'QUICK CHECKS');for(const [id,q] of Object.entries(quizData))pieces.push(id+': '+(state.answers[id]===undefined?'not answered':state.answers[id]===q.correct?'correct':'review needed'));const blob=new Blob([pieces.join('\n\n')],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='session-04-my-worksheet.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function glossaryHTML(query=''){return glossary.filter(x=>x.join(' ').toLowerCase().includes(query.toLowerCase())).map(([w,m])=>'<div class="glossary-item"><b>'+esc(w)+'</b><p>'+esc(m)+'</p></div>').join('')||'<p>No matching term.</p>';}
function timerText(){return String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0');}
function updateTimer(){const v=document.getElementById('timerValue'),b=document.getElementById('timerToggle');if(v)v.textContent=timerText();if(b)b.textContent=timerRunning?'Pause':'Start';}
function openDrawer(type){lastFocus=document.activeElement;document.getElementById('drawer').hidden=false;const title=document.getElementById('drawerTitle'),body=document.getElementById('drawerBody');if(type==='notes'){title.textContent='Teacher notes · '+(state.slide+1);body.innerHTML='<span class="teacher-pill">'+esc(sectionFor(state.slide).name)+' · '+sectionFor(state.slide).time+'-minute block</span><h3>'+esc(slides[state.slide].title)+'</h3><p>'+esc(slides[state.slide].notes)+'</p><hr class="divider"><h3>Help the student explain the foundation</h3><p>Ask: what information is needed, what rule or operation applies, what conclusion follows, and what evidence would change it? Let the student predict before revealing an answer.</p>';}else if(type==='outline'){title.textContent='Session contents';body.innerHTML='<div class="panel stack"><div class="row between"><h3>Class timer</h3><b id="timerValue">'+timerText()+'</b></div><div class="row"><button id="timerToggle">'+(timerRunning?'Pause':'Start')+'</button><button id="timerReset">Reset 120 min</button></div></div>'+slides.map((s,i)=>'<button class="outline-button '+(i===state.slide?'current':'')+'" data-outline-go="'+i+'"><span>'+String(i+1).padStart(2,'0')+'</span>'+esc(s.title)+'</button>').join('');}else if(type==='sources'){title.textContent='Sources and coverage';body.innerHTML='<p>Official Aptech class 4 covers Book Sessions 5 and 6: knowledge representation and types, knowledge/intelligence, the knowledge cycle, planning and decisions, reasoning types, propositional/predicate logic, performance analysis and metrics, and emerging/generative AI.</p><p>The supplied source is the April 2026 presenter’s outline. These explanations, examples, labs, and assignments supplement that outline. The full textbook and official question banks were not supplied.</p><a class="source-link04" href="https://aima.cs.berkeley.edu/" target="_blank" rel="noopener">Artificial Intelligence: A Modern Approach · knowledge and reasoning reference</a><a class="source-link04" href="https://scikit-learn.org/stable/modules/model_evaluation.html" target="_blank" rel="noopener">scikit-learn · model evaluation and metric definitions</a><a class="source-link04" href="https://www.nist.gov/publications/artificial-intelligence-risk-management-framework-generative-artificial-intelligence" target="_blank" rel="noopener">NIST · Generative AI Profile</a><p>Campus policies, message labels, and scores are fictional. Browser code uses a teaching subset. The grounding comparison is scripted and makes no model call. Metric calculations use the displayed fictional data.</p><p>Reference links support further teacher reading. Access to the offline activities does not require those sites.</p>';}else{title.textContent='Word bank';body.innerHTML='<label for="wordSearch" class="small">Find a term</label><input id="wordSearch" type="text" placeholder="Predicate, recall, grounding…"><div id="wordList">'+glossaryHTML()+'</div>';}document.getElementById('closeDrawer').focus();}
function closeDrawer(){document.getElementById('drawer').hidden=true;if(lastFocus?.isConnected)lastFocus.focus();}
stage.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.go!==undefined)return go(b.dataset.go);if(b.dataset.quiz){const id=b.dataset.quiz,a=Number(b.dataset.choice),q=quizData[id];state.answers[id]=a;save();document.querySelectorAll('[data-quiz="'+id+'"]').forEach(x=>x.setAttribute('aria-pressed',Number(x.dataset.choice)===a));const f=document.getElementById('feedback-'+id);f.textContent=(a===q.correct?'Yes. ':'Review the reason. ')+q.why;f.classList.toggle('bad',a!==q.correct);}if(b.dataset.knowledgeType){state.knowledgeType=b.dataset.knowledgeType;save();document.querySelectorAll('[data-knowledge-type]').forEach(x=>x.setAttribute('aria-pressed',x===b));document.getElementById('knowledgeDetail').innerHTML=typeHTML();}if(b.dataset.representation){state.representation=b.dataset.representation;save();document.querySelectorAll('[data-representation]').forEach(x=>x.setAttribute('aria-pressed',x===b));document.getElementById('representationDetail').innerHTML=representationHTML();}if(b.dataset.relation){const explanations={Amina:'Amina is an individual entity. “Instance of Student” places this person in the Student concept.',Student:'Student is a concept or class. Amina is an instance. The class is not the same thing as one individual.',Lab2:'Lab 2 is an individual room. “Part of” connects the room to a larger physical whole.',Building:'Science building is a whole that contains Lab 2. Its properties do not all automatically transfer to every part.',Course:'Course is a concept. “May enrol in” describes a possible relation, not proof that a specific enrolment happened.'};document.getElementById('relationDetail').textContent=explanations[b.dataset.relation];}if(b.id==='ruleStep'){state.ruleStep=Math.min(3,state.ruleStep+1);save();updateRules();}if(b.id==='ruleRun'){state.ruleStep=3;save();updateRules();}if(b.id==='ruleReset'){state.ruleStep=0;save();updateRules();}if(b.id==='toggleP'||b.id==='toggleQ'){const key=b.id==='toggleP'?'p':'q';state[key]=!state[key];b.textContent=key.toUpperCase()+': '+truth(state[key]);b.setAttribute('aria-pressed',state[key]);save();updateLogic();}if(b.dataset.person){state.people[b.dataset.person]=!state.people[b.dataset.person];save();render();}if(b.id==='runCode'){state.code=document.getElementById('codeEditor').value;state.codeOutput=runTeachingCode(state.code);save();document.getElementById('codeOutput').textContent=state.codeOutput;}if(b.id==='restoreCode'){state.code=INITIAL_CODE;state.codeOutput='';save();render();}if(b.dataset.codeLine!==undefined){const i=Number(b.dataset.codeLine);document.querySelectorAll('[data-code-line]').forEach(x=>x.setAttribute('aria-pressed',x===b));document.getElementById('lineDetail').innerHTML='<h3>Line '+(i+1)+'</h3><pre class="line04">'+esc(codeLines[i][0])+'</pre><p>'+codeLines[i][1]+'</p>';}if(b.dataset.threshold){state.threshold=Number(b.dataset.threshold);state.baseline=false;save();document.getElementById('threshold').value=state.threshold;document.getElementById('messageDetail').textContent='Select a message to explain its result.';updateMetrics();}if(b.id==='baselineBtn'){state.baseline=!state.baseline;save();document.getElementById('messageDetail').textContent='Select a message to explain its result.';updateMetrics();}if(b.dataset.message){const m=messages.find(m=>m.id===b.dataset.message),c=messageCategory(m);document.getElementById('messageDetail').textContent=m.id+': actual '+(m.spam?'spam':'normal')+', predicted '+(['tp','fp'].includes(c)?'spam':'normal')+'. '+({tp:'Correctly caught spam.',fp:'A normal message was wrongly flagged.',fn:'Spam was missed.',tn:'A normal message was correctly kept.'}[c]);}if(b.id==='generateDemo')showGenerated();if(b.id==='downloadWork'||b.id==='downloadFinal')downloadWork();if(b.id==='sourcesBtn')openDrawer('sources');});
stage.addEventListener('input',e=>{const t=e.target;if(t.dataset.field){state.worksheet[t.dataset.field]=t.value;save();}if(t.id==='codeEditor'){state.code=t.value;save();}if(t.id==='threshold'){state.threshold=Number(t.value);state.baseline=false;save();document.getElementById('messageDetail').textContent='Select a message to explain its result.';updateMetrics();}});
stage.addEventListener('change',e=>{const t=e.target;if(t.dataset.fact){state.facts[t.dataset.fact]=t.value==='unknown'?null:t.value==='true';state.ruleStep=0;save();updateRules();}if(t.id==='logicOperator'){state.operator=t.value;save();updateLogic();}if(t.id==='genQuestion'||t.id==='grounded'){if(t.id==='genQuestion')state.genQuestion=t.value;else state.grounded=t.checked;state.genOutput='';save();document.getElementById('genAnswer').textContent='Predict the evidence-supported answer, then show it.';document.getElementById('genAnswer').classList.remove('unsupported');document.getElementById('genWhy').textContent='';}});
document.getElementById('prevBtn').onclick=()=>go(state.slide-1);document.getElementById('nextBtn').onclick=()=>go(state.slide+1);document.getElementById('outlineBtn').onclick=()=>openDrawer('outline');document.getElementById('glossaryBtn').onclick=()=>openDrawer('glossary');document.getElementById('teacherBtn').onclick=()=>openDrawer('notes');document.getElementById('closeDrawer').onclick=closeDrawer;document.getElementById('fullscreenBtn').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch(e){document.getElementById('fullscreenBtn').textContent='Use browser full screen';}};
document.getElementById('drawer').addEventListener('click',e=>{if(e.target.id==='drawer')closeDrawer();const b=e.target.closest('button');if(!b)return;if(b.dataset.outlineGo!==undefined){closeDrawer();go(b.dataset.outlineGo);}if(b.id==='timerToggle'){timerRunning=!timerRunning;if(timerRunning)timerInterval=setInterval(()=>{if(seconds>0)seconds--;else{timerRunning=false;clearInterval(timerInterval);}updateTimer();},1000);else clearInterval(timerInterval);updateTimer();}if(b.id==='timerReset'){seconds=7200;timerRunning=false;clearInterval(timerInterval);updateTimer();}});
document.getElementById('drawer').addEventListener('input',e=>{if(e.target.id==='wordSearch')document.getElementById('wordList').innerHTML=glossaryHTML(e.target.value);});
document.addEventListener('keydown',e=>{const drawer=document.getElementById('drawer');if(e.key==='Escape'&&!drawer.hidden){closeDrawer();return;}if(!drawer.hidden){if(e.key==='Tab'){const all=[...drawer.querySelectorAll('button,input,textarea,select,a[href]')].filter(x=>!x.disabled),first=all[0],last=all.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}return;}if(/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||e.target.isContentEditable)return;if(e.key==='ArrowRight'){e.preventDefault();go(state.slide+1);}if(e.key==='ArrowLeft'){e.preventDefault();go(state.slide-1);}if(e.key==='Home'){e.preventDefault();go(0);}if(e.key==='End'){e.preventDefault();go(slides.length-1);}if(e.key.toLowerCase()==='n')openDrawer('notes');});
state.slide=Math.max(0,Math.min(slides.length-1,Number(state.slide)||0));render();
